def ledger(ops: list[str]) -> tuple[dict[str, int], list[int]]:
    balances: dict[str, int] = {}
    frozen: set[str] = set()
    history: list[tuple] = []
    rejected: list[int] = []

    def amount(token: str):
        if token and token.isdigit():
            return int(token)
        return None

    for i, op in enumerate(ops):
        tokens = op.split(" ")
        verb = tokens[0] if tokens else ""
        ok = False
        if verb == "open" and len(tokens) == 3:
            name, n = tokens[1], amount(tokens[2])
            if n is not None and name not in balances:
                balances[name] = n
                history.append(("open", name))
                ok = True
        elif verb == "deposit" and len(tokens) == 3:
            name, n = tokens[1], amount(tokens[2])
            if n is not None and n > 0 and name in balances:
                balances[name] += n
                history.append(("deposit", name, n))
                ok = True
        elif verb == "withdraw" and len(tokens) == 3:
            name, n = tokens[1], amount(tokens[2])
            if (
                n is not None
                and n > 0
                and name in balances
                and name not in frozen
                and balances[name] >= n
            ):
                balances[name] -= n
                history.append(("withdraw", name, n))
                ok = True
        elif verb == "transfer" and len(tokens) == 4:
            src, dst, n = tokens[1], tokens[2], amount(tokens[3])
            if (
                n is not None
                and n > 0
                and src != dst
                and src in balances
                and dst in balances
                and src not in frozen
                and balances[src] >= n
            ):
                balances[src] -= n
                balances[dst] += n
                history.append(("transfer", src, dst, n))
                ok = True
        elif verb == "freeze" and len(tokens) == 2:
            name = tokens[1]
            if name in balances and name not in frozen:
                frozen.add(name)
                history.append(("freeze", name))
                ok = True
        elif verb == "unfreeze" and len(tokens) == 2:
            name = tokens[1]
            if name in balances and name in frozen:
                frozen.remove(name)
                history.append(("unfreeze", name))
                ok = True
        elif verb == "undo" and len(tokens) == 1 and history:
            kind, *rest = history.pop()
            if kind == "open":
                del balances[rest[0]]
                frozen.discard(rest[0])
            elif kind == "deposit":
                balances[rest[0]] -= rest[1]
            elif kind == "withdraw":
                balances[rest[0]] += rest[1]
            elif kind == "transfer":
                balances[rest[0]] += rest[2]
                balances[rest[1]] -= rest[2]
            elif kind == "freeze":
                frozen.remove(rest[0])
            else:
                frozen.add(rest[0])
            ok = True
        if not ok:
            rejected.append(i)
    return balances, rejected
